const scene=document.getElementById('scene'),status=document.getElementById('status'),detail=document.getElementById('detail'),action=document.getElementById('action'),pause=document.getElementById('pause'),$=id=>document.getElementById(id);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),hp=n=>n>0&&n<1?Math.max(1,Math.round(n*1e6))+' HP':Math.round(n)+'M';
