let state=loadProgress(),savedRun=null,phase='',token=0,timers=[],enemyTickId=null,holdId=null,enemy=null,lastAttack=0,nextEnemy=0,paused=false,locked=false,doorTypes=[],pendingReward=null,preview=false,dustVisualPending=0,dustUntil=0;
function fresh(){return {cp:0,floor:0,lives:5,nextLife:0,party:[],captainId:null,ownedIds:[],xpById:{},summons:0,gold:0,attack:1,defense:1,best:0,tokens:0,protection:0,passives:{},mercy:0,firstRoom:true,dustPaid:[],defeatBag:[],lastDefeat:null,rivalBag:[],lastRival:null,trialBag:[],safeBag:[],lastRoom:null}}
function loadProgress(){const base=fresh();try{const p=JSON.parse(localStorage.getItem('tower-progress-v1')||'null');if(p&&p.schema===1){for(const k of ['cp','best','summons','gold','tokens'])if(Number.isSafeInteger(p[k])&&p[k]>=0)base[k]=p[k];for(const k of ['favor','mercy','grace','vessel','strength','guard'])if(p.passives?.[k]===true)base.passives[k]=true;for(const c of roster){const xp=p.xpById?.[c.id];if(Number.isSafeInteger(xp)&&xp>=0&&xp<=1000000000)base.xpById[c.id]=xp;}if(roster.some(c=>c.id===p.captainId))base.captainId=p.captainId;const old=Array.isArray(p.roster)?p.roster:[];base.ownedIds=roster.filter(c=>old.includes(c.id)||(Array.isArray(p.ownedIds)&&p.ownedIds.includes(c.id))||c.id===base.captainId).map(c=>c.id);const active=[...new Set([base.captainId,...old].filter(id=>base.ownedIds.includes(id)))].slice(0,2+[18,56,110].filter(f=>base.cp>=f).length);base.party=active.map(id=>memberFor(roster.find(c=>c.id===id),base.xpById));}}catch(e){}return base}
