function levelInfo(xp=0){xp=Math.max(0,Math.floor(xp));const level=Math.floor((1+Math.sqrt(1+8*xp/100))/2);return {level,current:xp-50*(level-1)*level,required:100*level};}
function memberFor(c,xps={}){const lv=levelInfo(xps[c.id]||0).level;const maxHP=Math.round(c.hp*(1+.02*(lv-1)));return {...c,hp:maxHP,current:maxHP};}
function captainAttackMultiplier(){return 1+(levelInfo(state.xpById[state.captainId]||0).level-1)*.01;}
