function chooseStartingParty(captain,companion){if(phase!=='select'||captain===companion)return;const a=roster.find(c=>c.id===captain),b=roster.find(c=>c.id===companion);if(!a||!b)return;const hasProgress=state.best>0||state.cp>0||state.tokens>0||state.summons>0||state.gold>0||state.ownedIds.length>1;state.ownedIds=[...new Set([captain,companion,...(hasProgress?state.ownedIds:[])])];state.captainId=captain;state.party=[memberFor(a,state.xpById),memberFor(b,state.xpById)];saveProgress();newRun();}
function captainSelect(){setScene('select','hall','CHOOSE YOUR PARTY','THE TOWER OF MULTIVERSES');const panel=document.createElement('div');panel.className='captainSelectPanel';scene.append(panel);let selected=null;function draw(){panel.replaceChildren();const heading=document.createElement('h2');heading.textContent=selected?'2. Choose your companion':'1. Choose your captain';const desc=document.createElement('p');desc.textContent=selected?'Captain: '+roster.find(c=>c.id===selected).name+'. Choose a different character to join your party.':'Start with two characters. Every party member earns permanent XP and levels.';panel.append(heading,desc);const grid=document.createElement('div');grid.className='captainGrid';panel.append(grid);for(const c of roster){const b=document.createElement('button');b.className='captainCard';b.dataset.captainId=c.id;b.disabled=selected===c.id;b.innerHTML='<img alt="" draggable="false"><strong></strong><span class="captainCardLevel"></span><span class="captainCardHP"></span><span class="captainChoose"></span>';b.querySelector('img').src=ART[c.id];b.querySelector('strong').textContent=c.name;b.querySelector('.captainCardLevel').textContent='LEVEL '+levelInfo(state.xpById[c.id]||0).level;b.querySelector('.captainCardHP').textContent='HP '+hp(memberFor(c,state.xpById).hp);b.querySelector('.captainChoose').textContent=b.disabled?'YOUR CAPTAIN':selected?'SELECT COMPANION':'SELECT CAPTAIN';b.onclick=()=>{if(selected)chooseStartingParty(selected,c.id);else{selected=c.id;draw();}};grid.append(b);}const foot=document.createElement('div');foot.className='captainSelectHint';foot.textContent='3rd slot: Floor 18 · 4th: Floor 56 · 5th: Floor 110';panel.append(foot);if(selected){const back=document.createElement('button');back.className='quiet';back.textContent='CHANGE CAPTAIN';back.onclick=()=>{selected=null;draw()};panel.append(back);}}draw();ui('Your adventure begins','Choose a captain and a companion from the available roster.');}
