 function frame(now){if(k!==token){clone.remove();return}const elapsed=now-begin;if(elapsed>=flyDuration){particles();return}const dt=Math.min(.033,Math.max(0,(now-last)/1000));last=now;let ax=0,ay=r.height*1.8;if(mode==='gravity'&&elapsed<550)ay=-r.height*1.6;if(mode==='whirlwind'){ax=-(y-r.height*.5)*5;ay=(x-r.width*.5)*4;}if(mode==='frost'){ay=r.height*2.4;spin*=Math.pow(.4,dt);}vx=clamp(vx+ax*dt,-r.width,r.width);vy=clamp(vy+ay*dt,-r.height*2,r.height*2);x+=vx*dt;y+=vy*dt;angle+=spin*dt;if(x<marginX||x>r.width-marginX){x=clamp(x,marginX,r.width-marginX);vx*=-.76;spin*=-.85}if(y<marginY||y>r.height-marginY){y=clamp(y,marginY,r.height-marginY);vy*=-.62;vx*=.85}lastX=x;lastY=y;clone.style.transform=`translate(${x-w/2}px,${y-h/2}px) rotate(${angle}rad)`;clone.style.opacity=String(1-Math.max(0,elapsed/flyDuration-.8)*2);requestAnimationFrame(frame);}
