let arenaMotion=null;
function stopArena(){if(arenaMotion){cancelAnimationFrame(arenaMotion.raf);arenaMotion=null;}}
function nextRival(){
 const eligible=rivals.filter(r=>!roster.some(c=>c.id===r.id));
 let bag=preview?previewRivalBag:state.rivalBag,last=preview?previewLastRival:state.lastRival;
 bag=(bag||[]).filter(id=>eligible.some(r=>r.id===id));
 if(!bag.length){bag=shuffle(eligible.map(r=>r.id));if(bag.length>1&&bag[0]===last)[bag[0],bag[1]]=[bag[1],bag[0]];}
 const id=bag.shift();if(preview){previewRivalBag=bag;previewLastRival=id;}else{state.rivalBag=bag;state.lastRival=id;}
 return eligible.find(r=>r.id===id)||eligible[0];
}
